#!/usr/bin/env python3
"""Build a standalone, offline comparison dashboard from saved hourly results.

Open dashboard.html in any modern browser. All values are embedded from the
reported full-year trajectories; slider weights rank *existing* controllers
and do not re-optimise or alter battery schedules.
"""
from __future__ import annotations

import json
import numpy as np
import pandas as pd

from battery_study import battery, config, controllers, data, metrics, validation

RUNS = {
    "S0 no battery": None,
    "S1 PV priority": "rule_strategies/S1_hourly.csv",
    "S2 peak shaving": "rule_strategies/S2_hourly.csv",
    "S3 price response": "rule_strategies/S3_hourly.csv",
    "S4 carbon response": "rule_strategies/S4_hourly.csv",
    "S5 min cost/carbon": "s5_multiobjective/S5_min_cost_hourly.csv",
    "S5 min peak": "s5_multiobjective/S5_min_peak_hourly.csv",
    "S5 balanced": "s5_multiobjective/S5_balanced_hourly.csv",
    "MPC perfect forecast, balanced (oracle)": "s6_mpc/S6_perfect_balanced_hourly.csv",
    "MPC persistence forecast, balanced": "s6_mpc/S6_persistence_balanced_hourly.csv",
}
KEYS = ["electricity_cost_currency", "carbon_emissions_kgco2", "peak_grid_import_kw"]


def payload() -> dict:
    inp = data.load_inputs()
    n = len(inp.df)
    if n != config.N_STEPS:
        raise ValueError(f"Expected {config.N_STEPS} source hours, found {n}")
    series = {}
    kpis = {}
    selected = json.loads((config.RESULTS / "rule_strategies" / "selected_parameters.json").read_text())
    p2 = selected["S2 peak shaving"]
    extra = {}
    for percent in (0, 50, 75):
        pol = controllers.s2_peak_shaving(inp, p2["target_kw"], percent / 100,
                                          p2["ceiling_kw"], p2["charge_hours"])
        x = battery.simulate_periodic(inp, pol)
        checks = validation.validate(x, periodic=True)
        if not checks.passed.all():
            raise AssertionError(f"Reserve {percent}% fails battery validation")
        extra[f"S2 reserve {percent}% (what-if)"] = x
    for name, rel in list(RUNS.items()) + [(n, None) for n in extra]:
        x = extra[name] if name in extra else (metrics.no_battery_frame(inp) if rel is None
                                               else pd.read_csv(config.RESULTS / rel))
        if len(x) != n or not np.array_equal(x.timestamp.to_numpy(), np.arange(n)):
            raise ValueError(f"{name} does not contain the complete ordered source year")
        k = metrics.kpis(x, capacity_kwh=float(inp.battery["capacity"]))
        kpis[name] = {key: round(float(k[key]), 6) for key in KEYS +
                      ["grid_import_kwh", "grid_export_kwh", "pv_self_consumption_fraction"]}
        series[name] = {key: np.round(x[key].fillna(0).to_numpy(dtype=float), 4).tolist()
                        if key in x else [0.0] * n
                        for key in ["grid_import_kwh", "grid_export_kwh", "soc_end_kwh",
                                    "battery_exchange_kwh"]}
    return {"context": {"case": "CityLearn 2022 Building_5 (Fontana, California)",
                         "hours": n, "capacity_kwh": float(inp.battery["capacity"]),
                         "currency": "source currency units; unspecified",
                         "note": "The first row is a source wrap-around hour. Source steps are used, not invented calendar dates."},
            "shared": {"load": np.round(inp.load, 4).tolist(),
                       "pv": np.round(inp.pv, 4).tolist(),
                       "price": np.round(inp.price, 4).tolist(),
                       "carbon": np.round(inp.carbon, 4).tolist()},
            "kpis": kpis, "series": series,
            "rankable": [n for n in RUNS if n.startswith(("S1 ", "S2 ", "S3 ", "S4 ", "S5 "))]}


# The approved website template is embedded here so the repository needs only one HTML file.
import base64
import zlib
_EMBEDDED_TEMPLATE = ''

def get_template() -> str:
    return zlib.decompress(base64.b64decode(_EMBEDDED_TEMPLATE)).decode("utf-8")


def main() -> None:
    """Rebuild the sole public/offline website: index.html."""
    template = get_template()
    if template.count("__PAYLOAD__") != 1:
        raise ValueError("Embedded template must have exactly one payload placeholder")
    js = json.dumps(payload(), separators=(",", ":"), ensure_ascii=False).replace("</", "<\\/")
    dest = config.ROOT / "index.html"
    dest.write_text(template.replace("__PAYLOAD__", js), encoding="utf-8")
    print(f"Saved {dest} ({dest.stat().st_size / 1e6:.1f} MB)")


if __name__ == "__main__":
    main()
